create database customer_shopping;

use customer_shopping;

select * from customer;

-- Q1. What is the total revenue generated by male vs female customers?
select gender , SUM(purchase_amount) AS revenue
from customer
group by gender;

-- Q2. which customers used a discount but still spent more than the average purchase amount?
select customer_id, purchase_amount
from customer
where discount_applied = 'Yes' and purchase_amount >= (select avg(purchase_amount)  from customer);

-- Q3. Which are the top 5 products with the highest average review rating?
select item_purchased , ROUND(AVG(review_rating),2) AS "Average Review Rating" 
from customer
group by item_purchased
order by AVG(review_rating) desc
 limit 5;

-- Q4. Compare the average purchase amounts between standrad and express shipping?
select shipping_type , round(avg(purchase_amount),2) AS "Average Purchase Amount"
 from customer
 where shipping_type in ('Express', 'Standard')
 group by shipping_type;

-- Q5. Do subscribed customer spend more? Compare average spend and total revenue between subscribers and non-subscribers?
select subscription_status ,
count(customer_id) as total_customers,
round(avg(purchase_amount),2) as avg_spent,
sum(purchase_amount) as total_revenue 
from customer
group by subscription_status
order by total_revenue, avg_spent desc;

-- Q6. Which 5 products have the highest percentage of purchases with discount applied?
select item_purchased ,
round(100 * sum(case when discount_applied = "Yes" then 1 else 0 end)/count(*),2) as discount_rate 
from customer
group by item_purchased
order by discount_rate desc
limit 5;

-- Q7. Segments customers into 'New' , 'Returning' , 'Loyal' based on their total 
-- number of previous purchases , and show the count for each segment.
with customer_type as (
select customer_id , previous_purchases,
CASE 
     WHEN previous_purchases = 1 THEN 'New'
     WHEN previous_purchases  between 2 and 10 THEN 'Returning'
     ELSE 'loyal'
     END AS customer_segment
from customer
)
select customer_segment, count(*) as "Number of Customer"
from customer_type
group by customer_segment;

-- Q8 What are top 3 most purchased products within each category?
with item_counts as(
select  category, item_purchased ,
count(customer_id) as total_counts,
ROW_NUMBER () over (partition by category order by count(customer_id) desc) as item_rank
from customer
 group by category, item_purchased
 )
select item_rank, item_purchased, category, total_counts
from item_counts
where item_rank <= 3;

-- Q9 Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select subscription_status, 
count(customer_id) as repeat_buyers
from customer
where previous_purchases > 5
group by subscription_status;

-- Q10. What is the revenue contribution of each age group?
select age_group,
sum(purchase_amount) as total_revenue
from customer 
group by age_group 
order by total_revenue desc;





 